import { Injectable, computed, signal } from '@angular/core';
import { TmdbMovie, WatchItem } from './movie';

const KEY = 'watchlist';

/**
 * Owns the watchlist state. A plain class-based store keeps the state local to
 * the app (no NgRx) and survives route changes, which is all this app needs.
 */
@Injectable({ providedIn: 'root' })
export class WatchlistStore {
  private _items = signal<WatchItem[]>(
    // Old items saved before these fields existed still load
    (JSON.parse(localStorage.getItem(KEY) ?? '[]') as WatchItem[])
      .map(m => ({ ...m, seen: m.seen ?? false }))
  );

  readonly items = this._items.asReadonly();

  watchedCount = computed(() => this._items().filter(m => m.seen).length);
  totalCount = computed(() => this._items().length);

  isOnList(id: number) {
    return this._items().some(m => m.id === id);
  }

  /** Add a movie unless it is already on the list. */
  add(movie: TmdbMovie) {
    this._items.update(items => {
      if (items.some(m => m.id === movie.id)) return items;
      const { poster_path, release_date, ...rest } = movie;
      return [...items, { ...rest, poster_path, release_date, seen: false }];
    });
  }

  remove(id: number) {
    this._items.update(items => items.filter(m => m.id !== id));
  }

  toggleWatched(id: number) {
    this._items.update(items =>
      items.map(m => (m.id === id ? { ...m, seen: !m.seen } : m))
    );
  }
}
```

